private static void add_implementation(
    INamedTypeSymbol implementationType,
    ISymbol interfaceMember,
    HashSet<ISymbol> entries)
{
    if (interfaceMember is IPropertySymbol property)
    {
        if (property.GetMethod is not null)
            add_implementation(implementationType, property.GetMethod, entries);
        if (property.SetMethod is not null)
            add_implementation(implementationType, property.SetMethod, entries);
