    int backShift = BitsPerLimb - smallShift;

    for (int i = 0; i < quotient.Length; i++)
    {
        nuint upper = (i + 1 < source.Length) ? source[i + 1] : 0;
        quotient[i] = (source[i] >> smallShift) | (upper << backShift);
    }
}
